#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static string hx2(int v) {
    static const char* D = "0123456789ABCDEF";
    return string(1, D[v >> 4]) + D[v & 15];
}
static string expected(long long n) {
    vector<int> groups;
    if (n == 0) groups.push_back(0);
    while (n > 0) {
        groups.push_back((int)(n & 0x7f));
        n >>= 7;
    }
    for (size_t i = 0; i + 1 < groups.size(); ++i) groups[i] |= 0x80;
    ostringstream os;
    for (size_t i = 0; i < groups.size(); ++i) {
        if (i) os << ' ';
        os << hx2(groups[i]);
    }
    return os.str();
}
static bool check(const string& exe, long long n, int id) {
    const string inF = "l4a09p2_in.txt", outF = "l4a09p2_out.txt";
    {
        ofstream o(inF);
        o << n << '\n';
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    string actual((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    while (!actual.empty() && (actual.back() == '\n' || actual.back() == '\r' || actual.back() == ' '))
        actual.pop_back();
    string want = expected(n);
    if (code != 0 || actual != want) {
        cout << "[FAIL] case " << id << ": n=" << n << ", expected=" << want
             << ", actual=" << actual.substr(0, 120) << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    vector<long long> tests = {
        0,                                        // 样例1
        926,                                      // 样例2
        987654321012345678LL,                     // 样例3
        1, 127, 128, 126,                         // 单组/跨组边界
        16383, 16384,                             // 2 组满值/跨 3 组
        1000000000000000000LL                     // 上界 10^18
    };
    srand(20230902);
    for (int t = 0; t < 20; ++t) {
        long long v = 0;
        int bits = 1 + rand() % 60;
        for (int b = 0; b < bits; ++b)
            if (rand() % 2) v = (v << 1) | 1;
        else v <<= 1;
        if (v > 1000000000000000000LL) v = 1000000000000000000LL;
        tests.push_back(v);
    }
    int passed = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(exe, tests[i], (int)i + 1)) ++passed;
    cout << "Results: " << passed << "/" << tests.size() << " passed" << '\n';
    return passed == (int)tests.size() ? 0 : 1;
}
